import Component from 'flarum/common/Component';
import Icon from 'flarum/common/components/Icon';
/** A series cover, or a plain stand-in with the title's first letter. */
export default class Cover extends Component {
  view() {
    const {
      url,
      title,
      className
    } = this.attrs;
    return url ? m("img", {
      className: 'AnthologyCover ' + (className || ''),
      src: url,
      alt: "",
      loading: "lazy"
    }) : m("span", {
      className: 'AnthologyCover AnthologyCover--blank ' + (className || ''),
      "aria-hidden": "true"
    }, m(Icon, {
      name: "fas fa-book-bookmark"
    }), m("span", {
      className: "AnthologyCover-letter"
    }, (title || '?').trim().charAt(0).toUpperCase()));
  }
}
flarum.reg.add('ernestdefoe-anthology', 'forum/components/Cover', Cover);